  const group=new THREE.Group();group.name='Verdance Gate landscape';VD.add(group);
  const mat=(c,r=.9)=>new THREE.MeshStandardMaterial({color:c,roughness:r,flatShading:true});
  const moss=mat(0x315f42),moss2=mat(0x477b4d),leaf=mat(0x286344),leaf2=mat(0x438b58),leaf3=mat(0x75a95c),bark=mat(0x59402b),stone=mat(0x667b68),stoneDark=mat(0x40594b),flowerM=[mat(0xffd36b),mat(0xff8fb0),mat(0xc5a4ff),mat(0xe8f4bd)];
