setInterval(()=>{const now=performance.now();let el=(now-simLast)/1000;simLast=now;if(document.hidden||!B)return;el=Math.min(Math.max(el,0),.5);
if(B.over){adv=0;simAcc=0;render();return}adv=0;
if(holdT>0){holdT=Math.max(0,holdT-el)}else if(!paused){simAcc+=el*speed;let n=0;while(simAcc>=SIM_DT&&n<20&&!B.over){step(B,SIM_DT);simAcc-=SIM_DT;n++}if(n>=20)simAcc=0}
render()},100);
document.addEventListener('visibilitychange',()=>{simLast=performance.now();simAcc=0;if(document.hidden){try{save()}catch(e){}}});
addEventListener('pagehide',()=>{try{save()}catch(e){}});
setInterval(()=>{save();afkUI()},5000);
/* ===== MODALS / ACTIONS ===== */
const M=h=>{$('#modal').innerHTML='<div>'+h+'<button data-a="close" style="width:100%;margin-top:10px">Close</button></div>';$('#modal').style.display='flex'};
const itStats=it=>`<div class="st"><span>${T[it.main][1]}</span><b>${fmt(it.main,iv(it,it.main,1))}</b></div>`+it.subs.map(s=>`<div class="st mu"><span>${T[s.k][1]}</span><span>${fmt(s.k,iv(it,s.k,s.w))}</span></div>`).join('');
function heroM(id){const s=stats(id),h=H[id],c=90*S.lv[id],a0=S.asc[id]||0,ac=15*(a0+1),ag=500*(a0+1);M(`<div class="hc">${spr(id)}<div><b style="font-size:18px">${h.n}</b> <span class="mu">${h.t}</span><div class="mu">${h.bio}</div></div></div>
<div class="card"><b>${h.sk}</b> — ${h.d}</div><div class="card"><b>⚡ ${h.ult}</b> — ${h.ud}</div><div class="st"><span>Level</span><b>${S.lv[id]}</b></div><div class="st"><span>HP</span><b>${Math.round(s.hp)}</b></div><div class="st"><span>ATK</span><b>${Math.round(s.atk)}</b></div><div class="st"><span>DEF</span><b>${Math.round(s.def)}</b></div><div class="st"><span>SPD</span><b>${Math.round(s.spd)}</b></div><div class="st"><span>CRIT</span><b>${(s.crit*100).toFixed(1)}%</b></div><div class="st"><span>Set bonus</span><b>+${Math.round(s.bonus*100)}%</b></div>
<div class="row"><button class="pri" data-a="lvup" data-v="${id}" ${S.gold<c||S.lv[id]>=cap(id)?'disabled':''}>Level up (${c}💰)</button><button data-a="mv" data-v="${id}|-1">◀ Forward</button><button data-a="mv" data-v="${id}|1">Back ▶</button></div>
<div class="row"><button class="pri" data-a="asc" data-v="${id}" ${S.lv[id]<cap(id)||a0>=5||S.shards<ac||S.gold<ag?'disabled':''}>Ascend ${a0}/5 → +15% stats, +10 lv cap (${ac}🔷 ${ag}💰)</button></div>
<div class="row">${[1,2,3,4,5].map(i=>`<button data-a="place" data-v="${id}|${i-1}">Team slot ${i}</button>`).join('')}</div>
${SLOTS.map(sl=>{const it=S.inv.find(i=>i.eq===id&&i.slot==sl);return`<div class="card" data-a="slot" data-v="${id}|${sl}" style="cursor:pointer;margin:4px 0;padding:6px 10px">${sl.toUpperCase()}: ${it?`<b style="color:${RC[it.r]}">${iname(it)}</b>`:'<span class="mu">empty</span>'}</div>`}).join('')}`)}
function itemM(id){const it=S.inv.find(i=>i.id==id),gc=Math.round(60*(it.lv+1)*(it.r+1)*(1+(it.st||1)/20)),sc=1+it.lv,sell=15*(it.r+1)*(1+it.lv);M(`<b style="color:${RC[it.r]};font-size:17px">${iname(it)}</b> <span class="mu">${RAR[it.r]} · from stage ${it.st}</span><div class="card">${itStats(it)}</div>
<div class="row">${S.owned.map(h=>`<button data-a="eq" data-v="${id}|${h}" ${it.eq==h?'disabled':''}>${H[h].n}</button>`).join('')}</div>
<div class="row">${it.eq?`<button data-a="uneq" data-v="${id}">Unequip</button>`:''}<button class="pri" data-a="enh" data-v="${id}" ${it.lv>=10||S.gold<gc||S.shards<sc?'disabled':''}>Enhance (${gc}💰 ${sc}🔷)</button><button data-a="sell" data-v="${id}" ${it.eq?'disabled':''}>Sell +${sell}💰</button></div>`)}
function slotM(id,sl){const L=S.inv.filter(i=>i.slot==sl&&i.eq!==id).sort((a,b)=>b.r-a.r);M(`<b>${H[id].n} — ${sl}</b>`+(L.map(it=>`<div class="card" data-a="eq2" data-v="${it.id}|${id}" style="border-color:${RC[it.r]};cursor:pointer"><b style="color:${RC[it.r]}">${iname(it)}</b> ${itStats(it)}</div>`).join('')||'<div class="mu">No spare items for this slot.</div>'))}
const act={autou(){S.autoU=S.autoU===false;if(B)B.autoU=S.autoU!==false;save();ctl()},afkopen(){const a=afkCalc();M(`<b style="font-size:18px">AFK rewards</b><div class="mu">${Math.floor(a.min)} min (max 24h)</div><div class="card">💰 ${a.gold} · XP ${a.xp}/hero · 🔷 ${a.shards} · Items ${a.items}</div><button class="pri" data-a="afk" style="width:100%">Collect</button>`)},snd(){S.snd=S.snd===false;save();if(S.snd)audioInit();if(MG)MG.gain.value=S.snd?.5:0;ctl()},tower(){view='battle';startBattle(S.tower+5,'tower')},
raid(){weekly();const d=new Date().toDateString();if(S.raid.day!==d){S.raid.day=d;S.raid.left=3}if(S.raid.left<1)return;S.raid.left--;save();view='battle';startBattle(10,'raid')},
rclaim(){const r=S.raid;if(r.claimed||r.mine+simDmg()<RPOOL)return;r.claimed=1;S.rel+=10;S.soul+=50;const it=rollItem(10,4);save();draw();M(`<b>Ouro defeated!</b><div class="card">+10🏺 +50💎<br><span style="color:${RC[it.r]}">${iname(it)}</span></div>`)},
arena(i){const a=S.arena,d=new Date().toDateString();if(a.day!==d){a.day=d;a.left=5}if(a.left<1)return;a.left--;view='battle';startBattle(10,'arena',a.opps[+i])},
aref(){if(S.gold>=50){S.gold-=50;genOpps();save();draw()}},
gnew(){const n=($('#gn').value||'').trim().slice(0,20);if(n){S.guild={name:n};save();draw()}},
gclaim(i){i=+i;if(S.cnt.c[i])return;const ok=[S.cnt.w>=15,S.cnt.rd>=1e5,S.tower>=5][i];if(!ok)return;S.cnt.c[i]=1;if(i==0)S.soul+=25;if(i==1)S.rel+=3;if(i==2)S.mith+=8;save();draw()},dg(k){regen();if(S.keys<1)return;if(S.keys>=5)S.keyT=Date.now();S.keys--;view='battle';startBattle(Math.max(1,S.cleared),k)},
asc(id){const a=S.asc[id]||0;if(S.lv[id]>=cap(id)&&a<5&&S.shards>=15*(a+1)&&S.gold>=500*(a+1)){S.shards-=15*(a+1);S.gold-=500*(a+1);S.asc[id]=a+1;save()}heroM(id);head()},
place(v){const[id,i]=v.split('|'),j=S.order.indexOf(id);if(j>=0)S.order[j]=S.order[+i];S.order[+i]=id;save();startBattle(S.sel);heroM(id)},
summon(n){n=+n;const c=n==1?100:450;if(S.soul<c)return;S.soul-=c;const rs=[];for(let i=0;i<n;i++){const id=rnd(RECR);let dup=S.owned.includes(id);if(dup){if((S.star[id]||0)<5)S.star[id]=(S.star[id]||0)+1;else S.shards+=20}else S.owned.push(id);rs.push({id,dup})}save();draw();M(rs.map(r=>`<div class="card hc">${spr(r.id)}<div><b>${H[r.id].n}</b><div>${r.dup?'Duplicate → ★ +1':'<span style="color:var(--gold)">NEW HERO!</span>'}</div></div></div>`).join(''))},
craft(s){if(S.mith<8||S.gold<300)return;S.mith-=8;S.gold-=300;const it=rollItem(Math.max(1,S.cleared),2,s);save();draw();M(`Forged <b style="color:${RC[it.r]}">${iname(it)}</b> (${RAR[it.r]})<div class="card">${itStats(it)}</div>`)},
fuse(r){r=+r;const f=free(r).slice(0,3);if(f.length<3)return;S.inv=S.inv.filter(i=>!f.includes(i));const it=rollItem(Math.max(...f.map(i=>i.st)),r+1);save();draw();M(`Fused into <b style="color:${RC[it.r]}">${iname(it)}</b> (${RAR[it.r]})<div class="card">${itStats(it)}</div>`)},
relup(k){const c=2*(S.rl[k]+1);if(S.rel>=c&&S.rl[k]<20){S.rel-=c;S.rl[k]++;save();draw()}},tab(v){view=v;draw()},pause(){paused=!paused;ctl()},speed(){speed=speed%3+1;ctl()},auto(){B.auto=S.auto=!B.auto;ctl();save()},
cast(id){const u=B.allies.find(a=>a.id==id);if(!B.over&&!u.dead&&!u.stun&&alive(B.enemies).length){if((u.en||0)>=100)ult(B,u);else if(u.skT<=0)cast(B,u)}},
afk(){const a=afkCollect();afkUI();head();M(`<b style="font-size:18px">AFK rewards collected</b><div class="card">💰 ${a.gold}<br>XP ${a.xp} per hero<br>🔷 ${a.shards}<br>Items ${a.items}</div>`)},
hero(id){heroM(id)},lvup(id){const c=90*S.lv[id];if(S.gold>=c&&S.lv[id]<60){S.gold-=c;S.lv[id]++;S.xp[id]=0;save()}heroM(id);head()},
mv(v){const[id,d]=v.split('|'),i=S.order.indexOf(id),j=i+ +d;if(i>=0&&j>=0&&j<5){[S.order[i],S.order[j]]=[S.order[j],S.order[i]];save();startBattle(S.sel)}heroM(id)},
slot(v){slotM(...v.split('|'))},eq2(v){const[i,h]=v.split('|');equip(i,h);heroM(h)},item(id){itemM(id)},
eq(v){const[i,h]=v.split('|');equip(i,h);itemM(i)},uneq(id){S.inv.find(i=>i.id==id).eq=null;save();itemM(id)},
enh(id){const it=S.inv.find(i=>i.id==id),g=Math.round(60*(it.lv+1)*(it.r+1)*(1+(it.st||1)/20)),s=1+it.lv;if(S.gold>=g&&S.shards>=s&&it.lv<10){S.gold-=g;S.shards-=s;it.lv++;save()}itemM(id);head()},
sell(id){const it=S.inv.find(i=>i.id==id);S.gold+=15*(it.r+1)*(1+it.lv);S.inv=S.inv.filter(i=>i!=it);save();act.close();draw()},
stage(s){view='battle';startBattle(+s)},close(){$('#modal').style.display='none';if(view!='battle')draw();head()}};
document.addEventListener('click',e=>{if(!AC)audioInit();const a=e.target.closest('[data-a]');if(a)act[a.dataset.a](a.dataset.v)});
/* ===== BOOT — ONE-TIME FRESH CAMPAIGN REQUESTED BY PLAYER ===== */
let __AWH_RESET_OCCURRED=false; /* v3.1.1: removed one-time boot wipe that erased saves lacking the reset marker */
load();weekly();const away=afkCalc();B=newBattle(Math.min(S.sel,S.cleared+1||1));draw();
if(__AWH_RESET_OCCURRED)M(`<b style="font-size:20px;color:var(--gold)">✦ NEW CAMPAIGN ✦</b><div class="mu">Your previous local campaign was reset as requested. All heroes are back to their starting level and the journey begins at Stage 1.</div><div class="card">Starting heroes: Lyra, Jax, Kira and Kai · Stage 1/100</div><div class="mu">Your new progress will be saved automatically.</div>`);
else if(away.min>=5)M(`<b style="font-size:18px">Welcome back, Owl</b><div class="mu">You were away ${Math.floor(away.min)} min.</div><div class="card">💰 ${away.gold} · XP ${away.xp}/hero · 🔷 ${away.shards} · Items ${away.items}</div><button class="pri" data-a="afk" style="width:100%">Collect AFK rewards</button>`);else if(S.pend){M('<b>'+S.pend+'</b>');S.pend='';save()}
